import{c as a,Q as e,j as s,m as n}from"./chunks/framework.DOi4mjdC.js";const T=JSON.parse('{"title":"TensorTrait简介","description":"","frontmatter":{},"headers":[{"level":1,"title":"TensorTrait简介","slug":"tensortrait简介"},{"level":2,"title":"需要包含的头文件","slug":"需要包含的头文件"},{"level":2,"title":"原型定义","slug":"原型定义"},{"level":2,"title":"模板参数","slug":"模板参数"},{"level":2,"title":"成员函数","slug":"成员函数"},{"level":2,"title":"相关接口","slug":"相关接口"},{"level":2,"title":"约束说明","slug":"约束说明"}],"relativePath":"api/SIMD-API/基础数据结构/TensorTrait/TensorTrait简介.md","filePath":"api/SIMD-API/基础数据结构/TensorTrait/TensorTrait简介.md"}'),o={name:"api/SIMD-API/基础数据结构/TensorTrait/TensorTrait简介.md"};function i(l,t,r,p,d,c){return e(),s("div",null,[...t[0]||(t[0]=[n(`<h1 id="tensortrait简介" tabindex="-1">TensorTrait简介 <a class="header-anchor" href="#tensortrait简介" aria-label="Permalink to &quot;TensorTrait简介&quot;">​</a></h1><p>TensorTrait数据结构是描述Tensor相关信息的基础模板类，包含Tensor的数据类型、逻辑位置和Layout内存布局。借助模板元编程技术，该类在编译时完成计算和代码生成，从而降低运行时开销。</p><h2 id="需要包含的头文件" tabindex="-1">需要包含的头文件 <a class="header-anchor" href="#需要包含的头文件" aria-label="Permalink to &quot;需要包含的头文件&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &quot;kernel_operator_tensor_trait.h&quot;</span></span></code></pre></div><h2 id="原型定义" tabindex="-1">原型定义 <a class="header-anchor" href="#原型定义" aria-label="Permalink to &quot;原型定义&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>template &lt;typename T, TPosition pos = TPosition::GM, typename LayoutType = Layout&lt;Shape&lt;&gt;, Stride&lt;&gt;&gt;&gt;</span></span>
<span class="line"><span>struct TensorTrait {</span></span>
<span class="line"><span>    using LiteType = T;</span></span>
<span class="line"><span>    using LiteLayoutType = LayoutType;</span></span>
<span class="line"><span>    static constexpr const TPosition tPos = pos; // 该常量成员为后续功能扩展做预留</span></span>
<span class="line"><span>public:</span></span>
<span class="line"><span>    __aicore__ inline TensorTrait(const LayoutType&amp; t = {});</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    __aicore__ inline LayoutType&amp; GetLayout();</span></span>
<span class="line"><span>    __aicore__ inline const LayoutType&amp; GetLayout() const;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    __aicore__ inline void SetLayout(const LayoutType&amp; t);</span></span>
<span class="line"><span></span></span>
<span class="line"><span>};</span></span></code></pre></div><h2 id="模板参数" tabindex="-1">模板参数 <a class="header-anchor" href="#模板参数" aria-label="Permalink to &quot;模板参数&quot;">​</a></h2><p><strong>表 1</strong> 模板参数说明</p><table tabindex="0"><thead><tr><th>参数名</th><th>描述</th></tr></thead><tbody><tr><td>T</td><td>只支持如下基础数据类型：int4b_t、uint8_t、int8_t、int16_t、uint16_t、bfloat16_t、int32_t、uint32_t、int64_t、uint64_t、float、half 。 在TensorTrait结构体内部，使用using关键字定义了一个类型别名LiteType，与模板参数T类型一致。 通过TensorTrait定义的LocalTensor/GlobalTensor不包含ShapeInfo信息。 例如：LocalTensor&lt;float&gt;对应的不含ShapeInfo信息的Tensor为LocalTensor&lt;TensorTrait&lt;float&gt;&gt;。</td></tr><tr><td>pos</td><td>数据存放的逻辑位置，Tposition类型，默认为TPosition::GM。</td></tr><tr><td>LayoutType</td><td>Layout数据类型，默认为空类型，即Layout&lt;Shape&lt;&gt;, Stride&lt;&gt;&gt;。 输入的数据类型LayoutType，需满足约束说明。</td></tr></tbody></table><h2 id="成员函数" tabindex="-1">成员函数 <a class="header-anchor" href="#成员函数" aria-label="Permalink to &quot;成员函数&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>__aicore__ inline TensorTrait(const LayoutType&amp; t = {})</span></span>
<span class="line"><span>__aicore__ inline LayoutType&amp; GetLayout()</span></span>
<span class="line"><span>__aicore__ inline const LayoutType&amp; GetLayout() const</span></span>
<span class="line"><span>__aicore__ inline void SetLayout(const LayoutType&amp; t)</span></span></code></pre></div><h2 id="相关接口" tabindex="-1">相关接口 <a class="header-anchor" href="#相关接口" aria-label="Permalink to &quot;相关接口&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// TensorTrait结构构造方法</span></span>
<span class="line"><span>template &lt;typename T, TPosition pos, typename LayoutType&gt;</span></span>
<span class="line"><span>__aicore__ inline constexpr auto MakeTensorTrait(const LayoutType&amp; t)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>// is_tensorTrait原型定义</span></span>
<span class="line"><span>template &lt;typename T&gt; struct is_tensorTrait</span></span></code></pre></div><h2 id="约束说明" tabindex="-1">约束说明 <a class="header-anchor" href="#约束说明" aria-label="Permalink to &quot;约束说明&quot;">​</a></h2><ul><li><p>同一接口不支持同时输入TensorTrait类型的GlobalTensor/LocalTensor和非TensorTrait类型的GlobalTensor/LocalTensor。</p></li><li><p>非TensorTrait类型和TensorTrait类型的GlobalTensor/LocalTensor相互之间不支持拷贝构造和赋值运算符。</p></li><li><p>TensorTrait特性当前仅支持如下接口：</p><div class="note custom-block github-alert"><p class="custom-block-title">说明</p><p></p><ul><li>和API配合使用时，当前暂不支持TensorTrait结构配置pos、LayoutType模板参数，需要使用构造函数构造TensorTrait，pos、LayoutType保持默认值即可。</li><li>DataCopy切片数据搬运接口需要ShapeInfo信息，不支持输入TensorTrait类型的GlobalTensor/LocalTensor。</li></ul></div><p><strong>表 2</strong> TensorTrait特性支持的接口列表</p></li></ul><table tabindex="0"><thead><tr><th>接口分类</th><th>接口名称</th></tr></thead><tbody><tr><td>基础API&gt;资源管理&gt;TQue/TQueBind</td><td>AllocTensor、FreeTensor、EnQue、DeQue</td></tr><tr><td>基础API&gt;矢量计算&gt;基础算术</td><td>Exp、Ln、Abs、Reciprocal、Sqrt、Rsqrt、Relu、Add、Sub、Mul、Div、Max、Min、Adds、Muls、Maxs、Mins、VectorPadding、BilinearInterpolation、Prelu、Mull、LeakyRelu</td></tr><tr><td>基础API&gt;矢量计算&gt;逻辑计算</td><td>And、Or、ShiftRight、ShiftLeft</td></tr><tr><td>基础API&gt;矢量计算&gt;复合计算</td><td>CastDequant、AddRelu、AddDeqRelu、SubRelu、MulAddDst、FusedMulAdd、MulAddRelu、AddReluCast、ExpSub、AbsSub、SubReluCast、MulCast</td></tr><tr><td>基础API&gt;数据搬运</td><td>DataCopy、Copy</td></tr><tr><td>基础API&gt;矩阵计算</td><td>Fill、LoadData、LoadDataWithTranspose、SetAippFunctions、LoadImageToLocal、LoadUnzipIndex、LoadDataUnzip、LoadDataWithSparse、Mmad、MmadWithSparse、BroadCastVecToMM、Gemm、Fixpipe</td></tr><tr><td>基础API&gt;矢量计算&gt;比较与选择</td><td>Compare、GetCmpMask、SetCmpMask、Select、GatherMask</td></tr><tr><td>基础API&gt;矢量计算&gt;类型转换</td><td>Cast、Truncate</td></tr><tr><td>基础API&gt;矢量计算&gt;归约计算</td><td>ReduceMax、BlockReduceMax、WholeReduceMax、ReduceMin、BlockReduceMin、WholeReduceMin、ReduceSum、BlockReduceSum、WholeReduceSum、RepeatReduceSum、PairReduceSum</td></tr><tr><td>基础API&gt;矢量计算&gt;数据转换</td><td>Transpose、TransDataTo5HD</td></tr><tr><td>基础API&gt;矢量计算&gt;数据填充</td><td>Brcb、Duplicate（仅支持不带scalar参数的接口）</td></tr><tr><td>基础API&gt;矢量计算&gt;离散与聚合</td><td>Gather、Gatherb、Scatter</td></tr><tr><td>基础API&gt;矢量计算&gt;数据重排（ISASI）</td><td>Interleave、DeInterleave</td></tr><tr><td>基础API&gt;矢量计算&gt;排序组合（ISASI）</td><td>ProposalConcat、ProposalExtract、RpSort16、MrgSort4、Sort32</td></tr></tbody></table>`,16)])])}const h=a(o,[["render",i]]);export{T as __pageData,h as default};
